changeSet.sql:
DO $do$
DECLARE
    current_data_type TEXT;
BEGIN
    SELECT data_type
      INTO current_data_type
      FROM information_schema.columns
     WHERE table_schema = current_schema()
       AND table_name = 'system_config'
       AND column_name = 'cfg_value';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'system_config.cfg_value is missing';
    ELSIF current_data_type = 'character varying' THEN
        ALTER TABLE system_config ALTER COLUMN cfg_value TYPE TEXT;
    ELSIF current_data_type = 'text' THEN
        NULL;
    ELSE
        RAISE EXCEPTION 'system_config.cfg_value has unsupported type: %', current_data_type;
    END IF;
END
$do$;
